#include <iostream>
using namespace std;

int main() {
    long long t, s, q, p = 0, ans = 0;
    cin >> t >> s >> q;

    while (s < t) {
        ++ans;
        for (long long i = 1; i <= s && s < t; ++i, ++p) {
            if (p % q == 0)
                s += q - 1;
        }
    }

    cout << ans;
    return 0;
}

